CREATE DATABASE IF NOT EXISTS mesto CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE mesto;
CREATE TABLE IF NOT EXISTS reservations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,phone VARCHAR(40) NOT NULL,email VARCHAR(190) NULL,guests INT NOT NULL DEFAULT 2, booking_date DATETIME NULL, message TEXT NULL,status VARCHAR(24) NOT NULL DEFAULT 'new',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_created_at(created_at));
